// LinkedIn — Minimum Window Substring (LeetCode 76), then the reported wrap-around variant.
public static class MinWindow {
    // Smallest substring of s containing every character of t, counting repeats. "" if none; leftmost on ties.
    public static string Find(string s, string t) {
        if (string.IsNullOrEmpty(s) || string.IsNullOrEmpty(t)) return "";
        var (start, len) = Scan(s, t, s.Length, int.MaxValue);
        return len == int.MaxValue ? "" : s.Substring(start, len);
    }

    // The same, but s is circular: a window may run off the end and continue from the start.
    // Scan s+s; a window longer than s is not a real circular window.
    public static string FindCircular(string s, string t) {
        if (string.IsNullOrEmpty(s) || string.IsNullOrEmpty(t)) return "";
        var (start, len) = Scan(s + s, t, s.Length, s.Length);
        return len == int.MaxValue ? "" : (s + s).Substring(start, len);
    }

    // Sliding window: grow right until every needed count is met, then shrink left while it still is.
    static (int Start, int Len) Scan(string s, string t, int maxStart, int maxLen) {
        var need = new Dictionary<char, int>();
        foreach (var c in t) need[c] = need.GetValueOrDefault(c) + 1;
        int missing = t.Length, l = 0, bestStart = 0, bestLen = int.MaxValue;
        for (int r = 0; r < s.Length; r++) {
            if (need.TryGetValue(s[r], out var n)) { if (n > 0) missing--; need[s[r]] = n - 1; }
            while (missing == 0) {
                int len = r - l + 1;
                if (len < bestLen && len <= maxLen && l < maxStart) { bestLen = len; bestStart = l; }
                if (need.TryGetValue(s[l], out var m)) { need[s[l]] = m + 1; if (m + 1 > 0) missing++; }
                l++;
            }
        }
        return (bestStart, bestLen);
    }
}
